create or replace function public.enforce_plan_limit() returns trigger language plpgsql security definer set search_path='' as $$ declare v_profile_id uuid; v_limit integer; v_count integer; v_key text; begin if tg_table_name='page_sections' then select p.profile_id into v_profile_id from public.pages p where p.id=new.page_id; v_key:='sections'; elsif tg_table_name in ('links','products','services') then select p.profile_id into v_profile_id from public.page_sections s join public.pages p on p.id=s.page_id where s.id=new.section_id; v_key:=tg_table_name; else return new; end if; if v_profile_id is null then raise exception 'Unable to determine profile for plan limit' using errcode='23503'; end if; perform pg_advisory_xact_lock(hashtextextended(v_profile_id::text,781239)); select coalesce((pl.limits->>v_key)::integer,-1) into v_limit from public.profiles pr join public.plans pl on pl.code=pr.plan_type where pr.id=v_profile_id and pl.is_active limit 1; if v_limit is null then v_limit:=-1; end if; if v_limit<0 then return new; end if; if tg_table_name='page_sections' then select count(*) into v_count from public.page_sections where page_id=new.page_id; elsif tg_table_name='links' then select count(*) into v_count from public.links l join public.page_sections s on s.id=l.section_id where s.page_id=(select page_id from public.page_sections where id=new.section_id); elsif tg_table_name='products' then select count(*) into v_count from public.products x join public.page_sections s on s.id=x.section_id where s.page_id=(select page_id from public.page_sections where id=new.section_id); else select count(*) into v_count from public.services x join public.page_sections s on s.id=x.section_id where s.page_id=(select page_id from public.page_sections where id=new.section_id); end if; if v_count>=v_limit then raise exception 'Plan limit reached for %',v_key using errcode='check_violation'; end if; return new; end; $$;
drop trigger if exists page_sections_plan_limit on public.page_sections;
drop trigger if exists links_plan_limit on public.links;
drop trigger if exists products_plan_limit on public.products;
drop trigger if exists services_plan_limit on public.services;
create trigger page_sections_plan_limit before insert on public.page_sections for each row execute function public.enforce_plan_limit();
create trigger links_plan_limit before insert on public.links for each row execute function public.enforce_plan_limit();
create trigger products_plan_limit before insert on public.products for each row execute function public.enforce_plan_limit();
create trigger services_plan_limit before insert on public.services for each row execute function public.enforce_plan_limit();
revoke all on function public.enforce_plan_limit() from public,anon,authenticated;
